/**
 * The master agreements, as written in FCH's own documents: the Master Partner
 * Agreement (FCH_Partner_Agreement_FCH-7618.docx), which partners sign with
 * FCH, and the Master Client Enrollment & Services Agreement
 * (FCH_Master_WLP_Client_Enrollment_Agreement.docx), which a partner's clients
 * (borrowers) sign. The wording is the documents' own; only the parts a builder
 * template does differently are adapted - the company's details are merge
 * fields, blanks the signer fills in are fields, the signature is a signing
 * card - at the very end, after the Schedules, in the client enrollment
 * agreement - and the docx's notes about its own highlighting and its
 * "remove this page" instructions are left out. Bracketed values such as
 * [B-1 Program Fee] are the Schedules' values, written in by the partner.
 */
export type TemplateNode =
    | ['header']
    | ['title' | 'subtitle' | 'h1' | 'h2' | 'h3' | 'p' | 'lines' | 'consent' | 'sign', string]
    | ['field', string, boolean]
    | ['ul', string[]]
    | ['table', string[] | null, string[][]];

