export const CLIENT_ENROLLMENT_AGREEMENT: TemplateNode[] = [
    ["header"],
    ["title", "BUSINESS CREDIT BUILDER &amp; FUNDING PROGRAM"],
    ["subtitle", "<strong>MASTER CLIENT ENROLLMENT &amp; SERVICES AGREEMENT</strong><br>White-Label Partner Edition"],
    ["table", ["Master Body Version: 1.0", "Body Issue Date: [MASTER BODY ISSUE DATE]"], [["Partner: {{owner.company_name}}", "Client Agreement Effective Date: {{today}}"]]],
    ["h3", "COMPOSITION OF THIS AGREEMENT"],
    ["p", "This Agreement consists of (i) this body, Sections 1 through 28, which is issued in standard form and is not subject to modification by the Company; and (ii) Schedule A (Partner Identity &amp; Notices), Schedule B (Fee Schedule), and Schedule C (Governing Law &amp; Venue), each of which is incorporated by reference and completed by the Company."],
    ["p", "<strong>Conflict. If a Schedule conflicts with this body, this body controls as to all legal and operative terms, and the Schedule controls only as to the identity, fee amounts, and jurisdiction values it is designed to state. No Schedule may add to, delete from, qualify, or modify any provision of this body.</strong>"],
    ["h1", "1. PARTIES &amp; AUTHORITY"],
    ["p", "This Client Enrollment &amp; Services Agreement (the “Agreement”) is entered into as of the Effective Date between the company identified below (the “Company”) and the client, borrower, or business entity identified below (the “Client”). The Company and the Client are each a “Party” and together the “Parties.”"],
    ["h3", "THE COMPANY"],
    ["table", null, [["<strong>Legal Name</strong>", "{{owner.company_name}}"], ["<strong>Doing Business As</strong>", "[A-2 Partner DBA]"], ["<strong>Entity Type / State</strong>", "[A-3 Entity Type] / [A-4 Formation State]"], ["<strong>Address</strong>", "{{owner.address}}"], ["<strong>Support Email</strong>", "{{owner.email}}"], ["<strong>Phone</strong>", "{{owner.phone}}"], ["<strong>Website</strong>", "[A-10 Website]"]]],
    ["h3", "THE CLIENT / BORROWER ENTITY"],
    ["table", null, [["<strong>Authorized Signer</strong>", "{{signer.name}}"], ["<strong>Company</strong>", "{{signer.business_name}}"], ["<strong>Address</strong>", "{{signer.business_address}}"], ["<strong>Email</strong>", "{{signer.email}}"], ["<strong>Phone</strong>", "{{signer.phone}}"]]],
    ["field", "Client entity type / formation state", true],
    ["field", "Client EIN", true],
    ["p", "The undersigned represents and warrants that they possess full legal authority to bind the Client and any applicable ownership interests. This Agreement is binding upon the Client, its owners, successors, and permitted assigns. If multiple owners execute or are obligated under this Agreement, their obligations shall be joint and several."],
    ["h1", "2. DEFINED TERMS"],
    ["p", "The following terms have the meanings set forth below. Defined terms are capitalized throughout this Agreement."],
    ["table", ["Term", "Definition"], [["<strong>Approval Notice Date</strong>", "The date on which a card issuer, creditor, vendor, or Capital Provider communicates an approval decision and a stated credit limit or approved amount, whether communicated to the Client, to the Company, or through the Platform."], ["<strong>Acceptance</strong>", "Client’s acceptance of an approved Business Credit Card, occurring on the earliest of: (i) Client accepting the issuer’s offer or the account being opened at Client’s request; (ii) the credit line becoming available to Client by any means, including a virtual or temporary card number, digital wallet, online account access, or physical card; or (iii) any use of the account. Physical delivery of a card is not required for Acceptance to occur."], ["<strong>Acceptance Date</strong>", "The date on which Acceptance occurs as to a given Business Credit Card."], ["<strong>Approval Round</strong>", "A coordinated group of applications submitted, sequenced, positioned, or materially assisted by the Company and decided within a rolling thirty (30) day window. Each Approval Round is evaluated separately for fee purposes."], ["<strong>Approved Credit Limit</strong>", "The initial revolving credit limit stated by the issuer in its approval for a Business Credit Card, measured as of the Approval Notice Date. The Approved Credit Limit excludes later credit limit increases except as provided in Section 8.4."], ["<strong>Business Credit Card</strong>", "A revolving credit card, charge card, or revolving line of credit issued in the legal name of the Client business entity for business or commercial purposes, whether or not the issuer requires a personal guaranty from an owner."], ["<strong>Schedules</strong>", "Schedule A (Partner Identity &amp; Notices), Schedule B (Fee Schedule), and Schedule C (Governing Law &amp; Venue), as completed by the Company and incorporated into this Agreement."], ["<strong>Capital Provider</strong>", "Any lender, funding source, creditor, vendor, card issuer, financing company, or other provider of credit or capital. The Company does not disclose the identity of its Capital Providers or its internal routing, matching, or submission logic."], ["<strong>Capital Access Advisory Fee</strong>", "The fee described in Section 8.2, calculated on Approved Credit Limits obtained in an Approval Round following the Company’s advisory services under Section 4.2(A)."], ["<strong>Platform</strong>", "The proprietary or licensed technology environment through which the Program is delivered, including its engines, underwriting and eligibility logic, workflows, sequencing rules, scoring, dashboards, and audit systems."], ["<strong>Program</strong>", "The Business Credit Builder &amp; Funding Program described in Sections 3 and 4."], ["<strong>Program Fee</strong>", "The Business Credit Builder enrollment fee described in Section 8.1, which is consideration for the Platform license and the services in Section 4.1 only."]]],
    ["h1", "3. PROGRAM STRUCTURE"],
    ["p", "Client enrolls in the Business Credit Builder &amp; Funding Program, delivered through the Company’s proprietary or licensed technology Platform."],
    ["p", "The Program may include structured progression through Tier 0 (Foundation), Tier 1 (Starter Vendor Credit), Tier 2 (Retail Expansion), Tier 3 (Fleet &amp; Cash Expansion), and Tier 4 (Institutional Funding Readiness)."],
    ["p", "Tier advancement is governed by system rules, underwriting validation, compliance controls, vendor or Capital Provider criteria, and eligibility sequencing. Client acknowledges that tiers and eligibility requirements are administered centrally, cannot be manually bypassed, and are not guaranteed."],
    ["h1", "4. PROGRAM DELIVERABLES &amp; PLATFORM ACCESS"],
    ["p", "During the initial twelve (12) month engagement term, Client receives structured advisory guidance, underwriting review, vendor sequencing strategy, funding-positioning analysis, and secure access to the Platform."],
    ["p", "All deliverables are advisory, strategic, administrative, and system-based in nature. The Company does not guarantee any specific credit approval, funding approval, credit limit, reporting outcome, Capital Provider decision, vendor approval, or funding amount."],
    ["h2", "4.1 Program Scope — Services Purchased by the Program Fee"],
    ["p", "The services in this Section 4.1 are the services purchased by the Program Fee under Section 8.1. They are delivered regardless of whether Client applies for, is approved for, or receives any credit or financing."],
    ["h3", "A. FUNDABILITY FOUNDATION"],
    ["ul", ["EIN and entity-setup support", "Business-name and entity consistency review", "Business address, telephone, website, and professional email review", "Business bank account and merchant account guidance", "Directory-listing and business-identity guidance"]],
    ["h3", "B. BUSINESS CREDIT BUILDING"],
    ["ul", ["D-U-N-S, Experian, Equifax, or comparable business-bureau setup guidance", "Tiered business-credit strategy (Tier 1 through Tier 4)", "Vendor-account sequencing, including Net 30, Net 55, Net 60, Net 90, or similar terms where available", "Retail, fleet, revolving, and cash-credit positioning", "Profile-correction or profile-improvement guidance where legally permissible and applicable"]],
    ["h2", "4.2 Capital Access Services — Not Purchased by the Program Fee"],
    ["p", "<strong>The services in this Section 4.2 are separate from the Program Fee and are compensated as set forth in Sections 8.2 and 8.5. Client pays no part of the Program Fee for these services.</strong>"],
    ["h3", "A. BUSINESS CREDIT CARD ADVISORY"],
    ["ul", ["Readiness evaluation and timing analysis for Business Credit Card applications", "Approval Round structuring, sequencing, and preparation guidance", "Application-readiness review and documentation preparation", "Compensated solely under Section 8.2, and only after an approval has issued"]],
    ["h3", "B. FUNDING STRATEGY &amp; CAPITAL ACCESS"],
    ["ul", ["Prequalification or readiness analysis for SBA financing, lines of credit, term loans, revenue-based financing, equipment financing, commercial real estate financing, and other products", "Capital Provider matching and submission support where available and authorized", "Equipment and commercial vehicle financing positioning, with or without a personal guaranty where available", "Client pays no fee to the Company for these services. The Company is compensated, if at all, by Capital Providers or through its platform provider, as stated in Sections 8.5 and 10."]],
    ["h2", "4.3 Phased Delivery Structure"],
    ["h3", "Phase 1 — Entity Compliance &amp; Fundability Setup"],
    ["ul", ["State-registration and good-standing review", "EIN confirmation and tax-identity consistency", "Business email, address, telephone, website, and directory-listing review", "Business bank account and merchant account guidance"]],
    ["h3", "Phase 2 — Business Credit Profile Development"],
    ["ul", ["Business-bureau registration and profile setup", "Tiered vendor strategy and sequencing", "Business-credit education and payment guidance", "Personal-guaranty versus no-personal-guaranty positioning"]],
    ["h3", "Phase 3 — Capital Access &amp; Approval Rounds (When Eligible; Outside the Program Fee)"],
    ["ul", ["Prequalification logic and Capital Provider matching", "Business Credit Card Approval Round sequencing and timing", "Loan-readiness package preparation", "Submission support where appropriate and authorized"]],
    ["h2", "4.4 Required Documentation"],
    ["p", "Client agrees to provide documents reasonably required to initiate onboarding, verify identity and authority, complete compliance review, and execute the Program. Required documentation may include:"],
    ["h3", "Basic Documentation"],
    ["ul", ["Government-issued photo identification", "EIN confirmation letter or equivalent tax document", "Articles of organization, incorporation, or comparable formation documents", "Most recent business bank statement (minimum one month, or more when required)", "Voided business check or bank-verification document", "Utility bill, lease, or other business-address verification"]],
    ["h3", "Optional / As Needed"],
    ["ul", ["D-U-N-S number or authorization to assist with registration", "Business plan, projections, tax returns, financial statements, debt schedule, or ownership information", "Lease, virtual-office, licensing, insurance, merchant-processing, or industry-specific documentation", "Additional Capital Provider, creditor, bureau, vendor, or compliance documents reasonably requested"]],
    ["p", "Client authorizes the Company to review submitted documentation and to disclose information reasonably necessary to approved third-party service providers, bureaus, creditors, vendors, processors, and Capital Providers for Program execution, verification, underwriting, and funding positioning, subject to applicable law and the Company’s privacy practices."],
    ["p", "Failure to provide complete and accurate documentation may delay onboarding, tier progression, credit-building activity, underwriting, or funding eligibility."],
    ["h1", "5. BUSINESS PURPOSE; NO CONSUMER CREDIT SERVICES"],
    ["p", "The Program is limited to credit, financing, and capital obtained in the legal name of the Client business entity for business or commercial purposes. Client acknowledges and agrees that:"],
    ["ul", ["The Company does not apply for, arrange, broker, or advise on consumer credit intended for personal, family, or household purposes, and no fee under this Agreement is charged for any such service.", "The Company is not a credit repair organization and does not offer, promise, or perform services to improve, correct, or alter any individual’s consumer credit report, credit history, or credit rating.", "Client shall not use the Program, the Platform, or any Company introduction to obtain consumer credit for personal, family, or household use.", "Certain card issuers require a personal guaranty from a business owner and may obtain a consumer credit report of that guarantor in connection with a business credit application. This does not convert business-purpose credit into consumer credit. Any such review is authorized only under a separate written credit authorization signed by the guarantor."]],
    ["p", "Client represents that all credit and capital sought under this Agreement is and will remain for bona fide business or commercial purposes. Client’s misuse of business credit for personal, family, or household purposes is a material breach of this Agreement."],
    ["h1", "6. PLATFORM GOVERNANCE &amp; SYSTEM CONTROLS"],
    ["p", "The Platform operates under role-based access controls, tenant data isolation, automated underwriting or eligibility engines, vendor sequencing logic, fundability scoring, audit logs, and data-cost protection controls. These controls are administered centrally and are not subject to Client modification, override, or reinterpretation."],
    ["p", "Client may not initiate paid bureau pulls, third-party data requests, creditor submissions, or funding applications through restricted Platform functions unless authorized. External data integrations and paid services are subject to Company approval, identity verification, permissible-purpose requirements, and cost controls."],
    ["p", "Platform activity may be logged, monitored, and audited for compliance, security, enforcement, dispute resolution, service improvement, and fraud prevention."],
    ["h1", "7. TERM &amp; PLATFORM ACCESS"],
    ["p", "The initial advisory engagement term is twelve (12) months from the Effective Date unless a different term is stated in a signed order form or addendum."],
    ["p", "Following the initial term, Client may retain access to the Platform dashboard and previously unlocked materials, subject to continued compliance, Platform availability, applicable subscription terms, and any third-party technology limitations."],
    ["p", "Ongoing advisory, monitoring, maintenance, or support beyond the initial term may be provided at the Company’s discretion or under a separate written agreement. If Schedule B states a post-term subscription amount, continued Platform access after the initial term requires payment of the amount stated at Schedule B, item B-6, billed in advance and cancellable on thirty (30) days’ written notice. If Schedule B states none, no post-term subscription applies."],
    ["h1", "8. PROGRAM INVESTMENT &amp; FEE SCHEDULE"],
    ["p", "Client agrees to pay the fees set forth in this Section 8. All amounts are stated in U.S. dollars. Fees are exclusive of any taxes, third-party costs, bureau fees, filing fees, or issuer charges, which remain the Client’s responsibility."],
    ["h2", "8.1 Business Credit Builder Program Fee"],
    ["table", ["Fee Component", "Amount / Terms"], [["<strong>Business Credit Builder Program Fee</strong>", "<strong>[B-1 Program Fee]</strong>"], ["<strong>What the Program Fee Purchases</strong>", "The Platform license and access described in Section 3, and the fundability foundation and business credit development services described in Section 4.1 (Tier 0 through Tier 4). The Program Fee purchases nothing else."], ["<strong>Payment Option A — Paid in Full</strong>", "<strong>[B-1 Program Fee]</strong> due on execution of this Agreement."], ["<strong>Payment Option B — Installments</strong>", "<strong>[B-2 Installment Plan]</strong>, as stated in Schedule B."], ["<strong>Activation / Platform Fee</strong>", "<strong>[B-3 Activation Fee]</strong>"], ["<strong>When Earned</strong>", "The Program Fee is earned as services are delivered and becomes fully earned and non-refundable upon the earliest of: (i) Platform access being granted; (ii) commencement of onboarding; (iii) commencement of a fundability or Tier 0 review; or (iv) the Company incurring third-party costs on Client’s behalf."]]],
    ["field", "Payment option selected (A — Paid in Full, or B — Installments)", true],
    ["p", "<strong>No portion of the Program Fee is consideration for arranging, brokering, procuring, submitting, or obtaining any extension of credit, commercial financing, or capital.</strong> The Program Fee purchases the Platform license and the business credit development services in Section 4.1, which are delivered regardless of whether Client applies for, is approved for, or receives any credit or financing. No portion of the Program Fee is contingent on any approval, credit limit, or funding outcome, and no portion is increased, reduced, or refunded based on any such outcome."],
    ["p", "The Program Fee does not purchase the capital access services in Section 4.2. Those services are compensated separately under Sections 8.2 and 8.5."],
    ["h2", "8.2 Capital Access Advisory Fee — Percentage of Approved Credit Limits"],
    ["table", null, [["<strong>Fee</strong>", "The percentage stated at Schedule B, item B-4 (<strong>[B-4 Advisory Fee %]</strong>) of the aggregate Approved Credit Limits obtained in an Approval Round."], ["<strong>Applies To</strong>", "Business Credit Cards obtained in a stacked Approval Round and individually approved Business Credit Cards, in each case obtained following the Company’s readiness evaluation, strategy, sequencing, preparation, or advisory assistance under Section 4.2(A). Client submits its own applications; the Company advises on readiness, structure, and timing."], ["<strong>When Earned</strong>", "The Capital Access Advisory Fee is earned as to each Business Credit Card upon approval and Acceptance of that card — that is, on the Acceptance Date. The Company’s services as to that card are complete at that point. The fee is never assessed, collected, or solicited before the Acceptance Date."], ["<strong>When Payable</strong>", "Due and payable within five (5) business days after the Acceptance Date. The Company may invoice an Approval Round once every approved card in that round has reached its Acceptance Date, or thirty (30) days after the first Acceptance Date in that round, whichever is earlier."], ["<strong>Calculation Basis</strong>", "The initial Approved Credit Limit stated by each issuer as of the Approval Notice Date, aggregated across all approvals in that Approval Round."], ["<strong>Charged Per Round</strong>", "Each Approval Round is calculated and invoiced separately. There is no cap on the number of Approval Rounds unless stated in a signed addendum."]]],
    ["h2", "8.3 How the Capital Access Advisory Fee Is Calculated"],
    ["p", "Illustrative example only, computed at a ten percent (10%) rate. The rate applicable to Client is the rate stated at Schedule B, item B-4. These figures are for explanation and do not represent a projection, expectation, or guarantee of any approval or credit limit."],
    ["table", ["Approval Round 1", "Approved Credit Limit"], [["<strong>Business Credit Card A</strong>", "$25,000"], ["<strong>Business Credit Card B</strong>", "$15,000"], ["<strong>Business Credit Card C</strong>", "$10,000"], ["<strong>Aggregate Approved Credit Limits</strong>", "<strong>$50,000</strong>"], ["<strong>Capital Access Advisory Fee (10%)</strong>", "<strong>$5,000 — due within 5 business days after approval and Acceptance</strong>"]]],
    ["p", "<strong>CLIENT ACKNOWLEDGMENT — PLEASE INITIAL: Client understands that this fee becomes payable only after a card is approved and accepted and the credit is available for use, whether or not a physical card has arrived; that a credit card provides a spending limit rather than a cash disbursement; and that the fee is owed whether or not Client draws on, transfers, liquidates, or uses the credit. Client is responsible for having funds available to pay this fee when due.</strong>"],
    ["field", "Client initials", true],
    ["h2", "8.4 Adjustments, Exclusions &amp; Attribution"],
    ["ul", ["Credit limit increases. Later credit limit increases on an existing account are excluded from the Approved Credit Limit, unless the increase is obtained through a new Approval Round or with the Company’s material assistance, in which case the increase is treated as a new Approved Credit Limit for that round.", "No acceptance, no fee. No fee is owed on any approval that is not accepted — whether because the issuer withdraws, rescinds, or conditions the approval, or because Client declines the offer and the account never opens. Any amount already paid on such an approval is credited to Client’s next Approval Round or refunded at the Company’s election.", "After Acceptance. Once a card is approved and accepted, the fee is fully earned and is not reduced or refunded if Client later closes or cancels the account, never activates or receives a physical card, or never uses the credit.", "Avoidance. If Client refuses or cancels an approved account for the purpose of avoiding this fee and then obtains substantially equivalent credit from the same issuer within twelve (12) months, that credit is treated as received for purposes of this Section 8 and is subject to Section 10.", "Declined applications. No Capital Access Advisory Fee is charged on any application that is declined.", "Consumer credit. No Capital Access Advisory Fee is charged on any consumer credit product, which is outside the scope of this Agreement under Section 5.", "Attribution period. Any Business Credit Card approved within twelve (12) months after the Company’s readiness evaluation, strategy, sequencing, preparation, or advisory assistance is presumed attributable to that assistance and subject to the Capital Access Advisory Fee, unless Client provides clear written documentation establishing an independent source.", "Disclosure duty. Client shall notify the Company of any approval subject to this Section 8 within forty-eight (48) hours after the Approval Notice Date, shall provide the issuer’s approval documentation showing the stated credit limit, and shall notify the Company within forty-eight (48) hours after each Acceptance Date.", "Deemed Acceptance. If Client does not confirm or deny the Acceptance Date within five (5) business days after the Company’s written request, Acceptance is deemed to have occurred on the tenth (10th) day after the Approval Notice Date, unless Client provides issuer documentation showing that the approval was withdrawn, declined, or accepted on a later date."]],
    ["h2", "8.5 No Advance Fee for Financing; Sources of Compensation"],
    ["p", "<strong>Every fee payable by Client under this Agreement is consideration for something Client has already received. Client pays no fee to the Company for arranging, brokering, submitting, or obtaining commercial financing, and the Company does not assess, collect, or solicit any fee from Client in advance of the closing of any commercial financing transaction.</strong>"],
    ["table", ["Fee", "What Client Receives", "When Charged"], [["Program Fee — Section 8.1", "Platform license and access, and the Tier 0–4 business credit development services in Section 4.1", "On enrollment, for services then being delivered"], ["Capital Access Advisory Fee — Section 8.2", "Approved and accepted business credit card accounts, with credit available to the business", "Only after approval and Acceptance"], ["Funding products — Section 10", "No fee of any kind", "Never — the Company is compensated by Capital Providers or through its platform provider, after funding"]]],
    ["p", "The Company’s compensation in connection with capital access is limited to the following:"],
    ["ul", ["The Capital Access Advisory Fee in Section 8.2, which is earned only after a card issuer has approved an account and stated a credit limit, and which is never assessed or collected before that approval; and", "Compensation the Company may receive from Capital Providers, or through its platform provider, in connection with funding products. That compensation is paid by those parties and not by Client, and Client owes nothing on account of it."]],
    ["p", "The Program Fee in Section 8.1 is consideration for the Platform license and the business credit development services in Section 4.1 only, and is not consideration for any commercial financing transaction."],
    ["h2", "8.6 Payment Authorization &amp; Method"],
    ["p", "Client authorizes the Company and its approved payment processors to charge the payment method on file for all amounts owed under this Section 8, including recurring installments under Section 8.1 and each Capital Access Advisory Fee under Section 8.2, on or after the date each amount becomes payable. Client shall maintain a valid payment method on file throughout the term and shall promptly update it upon any change."],
    ["p", "Accepted payment methods are those stated at Schedule B, item B-5. Client remains responsible for all scheduled amounts regardless of Platform usage, subject to applicable law and any written cancellation rights expressly stated in this Agreement."],
    ["p", "Amounts not paid when due accrue interest at the lesser of one and one-half percent (1.5%) per month or the maximum rate permitted by applicable law, together with reasonable collection costs."],
    ["h2", "8.7 Optional Additional Services"],
    ["p", "The optional services available under this Agreement, and their fees, are those stated at Schedule B, item B-7. Client is charged only for services it affirmatively selects in writing."],
    ["p", "Third-party costs — including bureau fees, state filing fees, registered-agent fees, directory-listing fees, and issuer charges — are the Client’s responsibility and are not included in any Company fee unless expressly stated above."],
    ["h1", "9. PAYMENT DEFAULT, CHARGEBACKS &amp; ACCELERATION"],
    ["p", "If any payment fails, reverses, is disputed, or is charged back, Client shall have three (3) calendar days after notice to cure the default. Failure to cure may result in restricted Platform access, suspension of services, termination, and collection activity."],
    ["p", "In the event of material breach, repeated payment default, undisclosed approval or funding, unauthorized circumvention, fraud, or chargeback initiation after service commencement, the Company may declare the remaining contractual balance — including the unpaid balance of the Program Fee and any earned but unpaid Capital Access Advisory Fee — immediately due and payable, and may pursue lawful collection remedies, including reasonable attorney fees, arbitration costs, and enforcement expenses where permitted."],
    ["p", "Client acknowledges that a chargeback does not constitute a lawful cancellation of this Agreement and may constitute material breach where services, Platform access, analysis, onboarding, third-party costs, or an Approval Round have commenced."],
    ["h1", "10. FUNDING COMPENSATION &amp; NON-CIRCUMVENTION"],
    ["p", "This Section 10 governs funding products other than Business Credit Cards. Business Credit Card compensation is governed exclusively by Section 8.2."],
    ["p", "<strong>Client owes the Company no fee, commission, success fee, or other compensation for funding or capital obtained in connection with these products. The Company is compensated, if at all, by Capital Providers or through its platform provider, and not by Client.</strong>"],
    ["p", "The Company will not condition any funding support on payment of a fee by Client, and will not invoice Client for any funding outcome. Any change to this arrangement would require a written amendment signed by both Parties and would not apply retroactively."],
    ["p", "Client may pursue funding independently. However, regarding any Capital Provider, creditor, vendor, card issuer, program, or capital source introduced, disclosed, positioned, or materially assisted by the Company, Client shall not directly or indirectly bypass, circumvent, conceal, or restructure a transaction to avoid compensation owed to the Company."],
    ["p", "Client must disclose funding involving a Company introduction within forty-eight (48) hours after approval or disbursement, as applicable. Funding obtained within twelve (12) months after a Company introduction or material assistance shall be presumed related to that introduction unless Client provides clear documentation establishing an independent source."],
    ["h1", "11. LIQUIDATED DAMAGES"],
    ["p", "If Client conceals a Business Credit Card approval or Acceptance, circumvents the Company, or fails to pay a Capital Access Advisory Fee owed under Section 8.2, the Company shall be entitled, to the extent enforceable, to recover the greater of: (i) the applicable Capital Access Advisory Fee; or (ii) ten percent (10%) of the concealed Approved Credit Limits, together with reasonable enforcement costs."],
    ["p", "<strong>No double recovery. </strong>The Company shall not recover both a Capital Access Advisory Fee and liquidated damages with respect to the same Approved Credit Limit. Amounts already paid are credited against any recovery under this Section 11."],
    ["p", "The Parties acknowledge that actual damages from concealed or circumvented approvals or funding may be difficult to calculate and agree that this amount represents a reasonable estimate of anticipated damages and is not intended as a penalty. A court or arbitrator may reduce this amount only to the extent required by applicable law."],
    ["h1", "12. CLIENT REPRESENTATIONS &amp; WARRANTIES"],
    ["p", "Client represents and warrants that:"],
    ["ul", ["All information and documentation supplied are truthful, accurate, current, and complete.", "The Client and its business activities comply with applicable federal, state, and local laws.", "The Client is an operating or bona fide business entity and all credit sought is for business or commercial purposes.", "No material financial, ownership, tax, banking, litigation, regulatory, criminal, or legal facts have been intentionally concealed.", "Client will not misuse the Platform, Program, vendor accounts, credit, or funding for fraudulent, deceptive, or unlawful purposes.", "Client will not knowingly misrepresent information to the Company, bureaus, creditors, vendors, card issuers, or Capital Providers.", "Client has authority to authorize credit, identity, bank, business, or underwriting reviews when separately consented to or legally permitted."]],
    ["p", "Material misrepresentation, fraud, identity misuse, document alteration, or unlawful conduct may result in immediate termination without refund and may be reported or disclosed where legally required."],
    ["h1", "13. CLIENT RESPONSIBILITIES"],
    ["p", "Client agrees to:"],
    ["ul", ["Provide accurate and timely documentation and respond promptly to requests.", "Follow compliance requirements, tier sequencing, application timing, and vendor or funding guidance.", "Apply only in the timing and sequence directed by the Company during an Approval Round, and avoid unnecessary, conflicting, duplicate, or unauthorized applications that may harm eligibility.", "Use personal guaranties, Social Security numbers, or consumer credit only when properly authorized and advised.", "Maintain a valid payment method on file and sufficient funds to satisfy fees when due.", "Maintain current contact, ownership, banking, and business information.", "Notify the Company promptly of material changes in revenue, ownership, address, banking, litigation, liens, defaults, credit, or business condition.", "Acknowledge that results vary based on Client conduct and third-party criteria."]],
    ["p", "Failure to satisfy these responsibilities may delay or prevent Program progression, creditor approvals, funding eligibility, reporting, or Platform access."],
    ["h1", "14. REFUND POLICY"],
    ["p", "Except where prohibited by law or expressly stated in a signed addendum, all fees are non-refundable once Platform access is granted, onboarding begins, a fundability or Tier 0 review commences, third-party costs are incurred, an Approval Round is submitted, or advisory services are delivered."],
    ["p", "Statutory cancellation right. If Schedule C, item C-4 states a cancellation period, Client may cancel this Agreement without penalty or obligation within that period after the Effective Date by delivering written notice to the Company at the notice address in Section 28, in which case all fees paid will be refunded within the period stated at item C-4, less documented third-party costs actually incurred. If item C-4 states none, no statutory cancellation period applies."],
    ["h1", "15. NO GUARANTEE; THIRD-PARTY DECISIONS"],
    ["p", "The Company is not a bank, direct lender, credit bureau, broker-dealer, financial institution, or guarantor of approval, and does not make final credit decisions. Creditors, bureaus, vendors, card issuers, Capital Providers, payment processors, and technology providers are independent third parties and make their own decisions. The Company does not control underwriting criteria, reporting times, approval amounts, credit limits, pricing, rates, terms, funding speed, or third-party availability."],
    ["p", "Platform evaluations, readiness scores, prequalifications, automated underwriting outputs, matching results, and recommendations support evaluation and workflow only. They are not final credit decisions, commitments, offers, or guarantees of approval."],
    ["h1", "16. LIMITATION OF LIABILITY"],
    ["p", "To the fullest extent permitted by law, the Company’s aggregate liability arising from this Agreement shall not exceed the total fees actually paid by Client to the Company during the twelve (12) months preceding the event giving rise to the claim."],
    ["p", "The Company shall not be liable for indirect, incidental, special, punitive, exemplary, or consequential damages; lost profits; lost business opportunities; Capital Provider, vendor, or issuer decisions; bureau reporting errors; funding delays; cybersecurity events outside the Company’s reasonable control; or third-party acts or omissions."],
    ["h1", "17. INDEMNIFICATION"],
    ["p", "Client shall defend, indemnify, and hold harmless the Company and its owners, officers, employees, contractors, agents, affiliates, technology licensors, successors, and permitted assigns from claims, losses, penalties, liabilities, damages, and reasonable expenses arising from Client misrepresentation, regulatory violations, fraud, unlawful conduct, misuse of credit or funding, breach of this Agreement, or infringement of third-party rights."],
    ["h1", "18. INDEPENDENT CONTRACTOR STATUS"],
    ["p", "Nothing in this Agreement creates a partnership, joint venture, agency, fiduciary relationship, franchise, employment relationship, or lender-borrower relationship between the Company and Client. The Company provides advisory, administrative, technology-enabled, and placement-support services as an independent contractor."],
    ["h1", "19. INTELLECTUAL PROPERTY &amp; PLATFORM USE"],
    ["p", "The Platform, workflows, training materials, analyses, scoring logic, forms, branding, vendor sequences, funding strategies, reports, and related intellectual property are owned by or licensed to the Company. Client receives a limited, non-exclusive, non-transferable, revocable right to use the Platform and Program materials for Client’s internal business purposes during authorized access."],
    ["p", "Third-party licensor. The Platform is licensed to the Company by a third-party technology provider that retains all right, title, and interest in the Platform, its engines, underwriting and eligibility logic, workflows, sequencing rules, configurations, and data architecture. That provider is an intended third-party beneficiary of this Section 19 and of Sections 16 and 20, and may enforce those provisions directly. Client acquires no right, title, license, or interest in the Platform beyond the limited access right granted in this Agreement."],
    ["p", "Client may not copy, resell, reverse engineer, scrape, disclose, sublicense, publish, or use restricted Company or licensor materials to create or support a competing service without prior written consent."],
    ["h1", "20. CONFIDENTIALITY &amp; DATA AUTHORIZATION"],
    ["p", "Each Party shall use reasonable measures to protect confidential business, financial, personal, technical, and proprietary information received from the other. The Company may process, store, analyze, and transmit Client information as reasonably necessary to deliver the Program, operate the Platform, prevent fraud, comply with law, and engage authorized service providers."],
    ["p", "<strong>Company confidential information includes Capital Provider and card issuer identities, internal eligibility thresholds, routing and matching logic, submission strategy, underwriting rules, sequencing methodology, and pricing structures. Client shall not disclose, publish, or use such information for any purpose other than receiving the Program.</strong>"],
    ["p", "Any consumer credit report, bank-data access, identity verification, electronic-signature consent, or other legally regulated authorization shall be governed by a separate authorization or disclosure when required."],
    ["h1", "21. ASSIGNMENT"],
    ["p", "Client may not assign this Agreement without the Company’s prior written consent. The Company may assign this Agreement in connection with a merger, acquisition, restructuring, financing, sale of assets, change of control, technology transition, or transfer to an affiliate or successor."],
    ["h1", "22. SEVERABILITY; WAIVER"],
    ["p", "If any provision is held invalid or unenforceable, it shall be enforced to the maximum lawful extent and the remaining provisions shall remain in effect. Failure to enforce any provision is not a waiver of future enforcement."],
    ["h1", "23. FORCE MAJEURE"],
    ["p", "The Company shall not be liable for delay, interruption, or failure caused by events beyond its reasonable control, including natural disasters, severe weather, war, terrorism, civil unrest, labor disputes, governmental action, public-health events, cyberattacks, utility failure, vendor outage, internet interruption, banking disruption, or infrastructure failure."],
    ["h1", "24. DISPUTE RESOLUTION; GOVERNING LAW"],
    ["p", "This Agreement shall be governed by the laws of the State of <strong>[C-1 Governing State]</strong>, without regard to conflict-of-laws rules. The exclusive venue for any permitted court proceeding shall be <strong>[C-2 Venue County]</strong> County, <strong>[C-1 Governing State]</strong>, unless applicable law requires otherwise."],
    ["p", "Before filing arbitration, the Parties shall attempt in good faith to resolve the dispute through written notice and informal negotiation, followed by mediation if requested. Unresolved disputes shall be determined by binding arbitration administered by <strong>[C-3 Arbitration Provider]</strong> under its applicable commercial rules, seated in <strong>[C-3 Arbitration Seat]</strong>."],
    ["p", "The Parties waive trial by jury and participation in any class, collective, consolidated, or representative action to the fullest extent permitted by law. The Company may seek temporary, preliminary, or permanent injunctive relief for fraud, data misuse, confidentiality breach, non-circumvention, or intellectual-property violations."],
    ["h1", "25. SURVIVAL"],
    ["p", "The provisions relating to payment obligations, the Capital Access Advisory Fee, non-circumvention, liquidated damages, confidentiality, data use, intellectual property, limitation of liability, indemnification, attorney fees, dispute resolution, and any provision that by its nature should survive shall remain effective after expiration or termination."],
    ["h1", "26. ELECTRONIC EXECUTION"],
    ["p", "This Agreement may be signed electronically and in counterparts. Electronic signatures, click-through acceptance, and electronically stored copies shall have the same legal effect as originals to the fullest extent permitted by law."],
    ["h1", "27. ENTIRE AGREEMENT &amp; AMENDMENTS"],
    ["p", "This Agreement, together with any signed order form, payment schedule, credit authorization, privacy notice, success-fee addendum, or other expressly incorporated document, constitutes the entire agreement between the Parties concerning the Program and supersedes prior oral or written discussions on the same subject."],
    ["p", "Any amendment, waiver, or modification must be in writing and signed or electronically accepted by authorized representatives of both Parties. Additional owners or guarantors may be added through the Platform or by written addendum."],
    ["h1", "28. NOTICES"],
    ["table", null, [["<strong>Company Legal Name</strong>", "{{owner.company_name}}"], ["<strong>Attention</strong>", "<strong>[A-11 Authorized Representative]</strong>"], ["<strong>Address</strong>", "{{owner.address}}"], ["<strong>Notice Email</strong>", "<strong>[A-12 Notice Email]</strong>"], ["<strong>Support Email</strong>", "{{owner.email}}"], ["<strong>Phone</strong>", "{{owner.phone}}"], ["<strong>Copy To (optional)</strong>", "<strong>[A-13 Copy-To Email]</strong>"]]],
    ["p", "Formal notices shall be delivered by confirmed electronic delivery, nationally recognized overnight service, or certified mail, return receipt requested. Notice is deemed received upon confirmed electronic delivery, documented refusal, or delivery confirmation."],
    ["h1", "EXHIBIT A — FEE SCHEDULE SUMMARY"],
    ["p", "This Exhibit A summarizes the fees stated in Section 8. In the event of any conflict, Section 8 controls."],
    ["table", ["Fee", "Amount", "When Charged"], [["Business Credit Builder Program Fee (Platform + Tiers 0–4)", "<strong>[B-1 Program Fee]</strong>", "On execution, or per the installment schedule selected in Section 8.1"], ["Capital Access Advisory Fee", "<strong>[B-4 Advisory Fee %]</strong> of aggregate Approved Credit Limits per Approval Round", "Earned only on approval and Acceptance of the card; payable within 5 business days. Never collected in advance."], ["Activation / Platform Fee", "<strong>[B-3 Activation Fee]</strong>", "On execution, if applicable"], ["Funding fees on non-card products", "None — Client pays nothing", "Company is compensated by Capital Providers or its platform provider (Sections 8.5 and 10)"], ["Optional Additional Services", "Per Schedule B, item B-7", "As selected"], ["Third-Party Costs", "At cost", "As incurred — Client responsibility"]]],
    ["h3", "PROGRAM SUMMARY OVERVIEW"],
    ["p", "This structured Program is designed to help establish a fundable business foundation, develop business-credit profiles responsibly, improve capital readiness, and position the Client for business-purpose financing opportunities. Results depend on Client qualifications, documentation, compliance, market conditions, creditor and Capital Provider criteria, and third-party decisions. No specific approval, credit limit, or funding amount is promised or guaranteed."],
    ["h1", "SCHEDULE A — PARTNER IDENTITY &amp; NOTICES"],
    ["p", "Completed by the Company. These values populate the corresponding blue fields in the body of this Agreement."],
    ["table", ["Item", "Value"], [["<strong>A-1  Partner Legal Name</strong>", "{{owner.company_name}}"], ["<strong>A-2  Partner DBA / Brand</strong>", "[BRAND NAME AS PRESENTED TO CLIENTS]"], ["<strong>A-3  Entity Type</strong>", "[LLC / CORPORATION / OTHER]"], ["<strong>A-4  Formation State</strong>", "[STATE]"], ["<strong>A-5 / A-6  Address</strong>", "{{owner.address}}"], ["<strong>A-7  Support Email</strong>", "{{owner.email}}"], ["<strong>A-8  Phone</strong>", "{{owner.phone}}"], ["<strong>A-9  Partner Logo</strong>", "The logo in the header of this Agreement"], ["<strong>A-10  Website / Domain</strong>", "[WEBSITE]"], ["<strong>A-11  Authorized Representative</strong>", "[NAME] / [TITLE]"], ["<strong>A-12  Notice Email</strong>", "[NOTICE EMAIL — may differ from support]"], ["<strong>A-13  Copy-To Email (optional)</strong>", "[COUNSEL OR SECONDARY EMAIL, OR “None”]"]]],
    ["h1", "SCHEDULE B — FEE SCHEDULE"],
    ["p", "<strong>Completed by the Company within the permitted ranges below. Values outside a permitted range are not available and will not be accepted.</strong>"],
    ["table", ["Item", "Permitted Range", "Partner’s Value"], [["<strong>B-1  Business Credit Builder Program Fee</strong><br><strong>(Platform license + Tier 0–4)</strong>", "[FLOOR] to [CEILING]", "[VALUE]"], ["<strong>B-2  Installment Plan</strong><br><strong>(if Payment Option B is offered)</strong>", "Maximum [MAX NUMBER] installments over no more than [MAX MONTHS] months; aggregate not to exceed [MAX TOTAL]", "[NUMBER] installments of [AMOUNT], billed [FREQUENCY]; total [TOTAL] — or “Not offered”"], ["<strong>B-3  Activation / Platform Fee</strong>", "[RANGE, OR “Must be included in B-1”]", "[VALUE, OR “Included in B-1”, OR “Not applicable”]"], ["<strong>B-4  Capital Access Advisory Fee</strong><br><strong>(percentage of Approved Credit Limits)</strong>", "[FLOOR %] to [CEILING %]", "[VALUE %]"], ["<strong>B-5  Accepted Payment Methods</strong>", "Approved processors only", "[ACH / BUSINESS DEBIT / CARD / WIRE]"], ["<strong>B-6  Post-Term Subscription</strong>", "[RANGE, OR “None permitted”]", "[AMOUNT] per [MONTH/YEAR], or “None”"], ["<strong>B-7  Optional Additional Services</strong>", "Each service no more than [CEILING]. No optional service may be a fee for arranging, brokering, or obtaining financing.", "1. [SERVICE] — [FEE]<br>2. [SERVICE] — [FEE]<br>3. [SERVICE] — [FEE]<br>4. [SERVICE] — [FEE]<br>or “None”"]]],
    ["h3", "SCHEDULE B GOVERNING RULES"],
    ["ul", ["A value outside its permitted range is not available under this program and may not be presented to a client.", "No fee stated in this Schedule may be charged for arranging, brokering, submitting, or obtaining commercial financing. Section 8.5 of the body governs and controls.", "The Program Fee at B-1 is consideration for the Platform license and the Section 4.1 services only. It may not be described, marketed, or invoiced as a fee for funding or credit approval.", "The Capital Access Advisory Fee at B-4 is earned only on approval and Acceptance of a Business Credit Card, as defined in the body. It may not be collected earlier by any means.", "Client pays no fee for funding products. Nothing may be added to this Schedule that would change that."]],
    ["h1", "SCHEDULE C — GOVERNING LAW &amp; VENUE"],
    ["p", "Completed by the Company. Each value should be confirmed by licensed counsel for the states in which the Company operates and solicits."],
    ["table", ["Item", "Value"], [["<strong>C-1  Governing State</strong>", "[STATE]"], ["<strong>C-2  Venue County</strong>", "[COUNTY]"], ["<strong>C-3  Arbitration Provider and Seat</strong>", "[PROVIDER] / [CITY, STATE]"], ["<strong>C-4  Statutory Cancellation Period</strong>", "[NUMBER] days, with refund within [NUMBER] days — or “None”. State only a period that applicable law requires; confirm with counsel before stating any period."]]],
    ["h3", "ACKNOWLEDGMENT OF AUTHORIZED SIGNATURE"],
    ["p", "By signing below, the undersigned certifies that they are authorized to execute this Agreement on behalf of the Client, have reviewed and accepted all terms — including the Capital Access Advisory Fee in Section 8.2 and the refund policy in Section 14 — and authorize the Company to verify identity and signing authority using identification and business-formation documents provided through the Platform or other approved methods."],
    ["table", null, [["<strong>Company representative</strong>", "[A-11 Authorized Representative]"], ["<strong>Company</strong>", "{{owner.company_name}}"]]],
    ["consent", "I am authorized to sign for the Client, and I accept all terms of this Agreement, including the Capital Access Advisory Fee in Section 8.2 and the refund policy in Section 14"],
    ["field", "Title", true],
    ["sign", "Client authorized signer"],
];
